#!/usr/bin/env python3"""Test MQTT message flow - subscribe locally and receive messages"""import paho.mqtt.client as mqttimport jsonimport timeimport threadingreceived_messages = []def on_message(client, userdata, msg):    payload = msg.payload.decode('utf-8')    print(f"Γ£ô RECEIVED on '{msg.topic}': {payload[:80]}")    received_messages.append((msg.topic, payload))def on_connect(client, userdata, flags, rc):    if rc == 0:        print(f"Γ£ô Subscriber connected successfully")        client.subscribe("sensors/gas")        print(f"Γ£ô Subscribed to sensors/gas")    else:        print(f"Γ£ù Connection failed with code {rc}")# Create subscribersub_client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION1)sub_client.on_connect = on_connectsub_client.on_message = on_messagesub_client.connect("localhost", 1883, 60)# Run subscriber in backgroundsub_thread = threading.Thread(target=sub_client.loop_forever, daemon=True)sub_thread.start()# Wait for connectiontime.sleep(1)# Now publish a messageprint("\nPublishing test message...")pub_client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION1)pub_client.connect("localhost", 1883, 60)pub_client.loop_start()payload = {"test": "message", "timestamp": int(time.time() * 1000)}pub_client.publish("sensors/gas", json.dumps(payload))print(f"Γ£ô Published: {payload}")# Wait to receivetime.sleep(2)# Cleanuppub_client.loop_stop()pub_client.disconnect()sub_client.disconnect()sub_client.loop_stop()if received_messages:    print(f"\nΓ£ô SUCCESS: Received {len(received_messages)} message(s)")else:    print(f"\nΓ£ù FAIL: No messages received!")